prog='''def transform(grid):
    h, w = len(grid), len(grid[0])
    ones = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == 1]
    # pair 1-markers lying on opposite grid edges in the same row/column -> full lines
    lines = []
    for (r1, c1) in ones:
        for (r2, c2) in ones:
            if (r1, c1) >= (r2, c2):
                continue
            if c1 == c2 and ((r1 == 0 and r2 == h - 1)):
                lines.append(('v', c1))
            if r1 == r2 and (c1 == 0 and c2 == w - 1):
                lines.append(('h', r1))
    out = [row[:] for row in grid]
    def on_line(r, c):
        return any((t == 'v' and c == k) or (t == 'h' and r == k) for t, k in lines)
    # recolor every 2-block whose cells touch a line (share an edge with it)
    seen = [[False] * w for _ in range(h)]
    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] == 2 and not seen[r0][c0]:
                comp = [(r0, c0)]
                seen[r0][c0] = True
                blk = []
                while comp:
                    r, c = comp.pop()
                    blk.append((r, c))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and not seen[nr][nc]:
                            seen[nr][nc] = True
                            comp.append((nr, nc))
                if any(on_line(r, c) or
                       on_line(r + dr, c + dc)
                       for r, c in blk
                       for dr, dc in ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1))):
                    for r, c in blk:
                        if 0 <= r < h and 0 <= c < w:
                            out[r][c] = 1
    # draw the full lines
    for t, k in lines:
        if t == 'v':
            for r in range(h):
                out[r][k] = 1
        else:
            for c in range(w):
                out[k][c] = 1
    return out
'''
